// ── SAFETY LAYER 1 : Twilio Signature Validation ────────────────────────────
// Twilio signs every request with X-Twilio-Signature using your Auth Token.
// Distributed rate limiting + signature validation via Redis (Upstash REST).
// Env: REDIS_CONNECTION_URL, REDIS_REST_TOKEN, N8N_TWILIO_AUTH_TOKEN, N8N_WEBHOOK_BASE_URL

const crypto = require('crypto');

function timingSafeEqualStrings(a, b) {
  const sa = String(a ?? '');
  const sb = String(b ?? '');
  const ba = Buffer.from(sa, 'utf8');
  const bb = Buffer.from(sb, 'utf8');
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

async function redisIncrWindow(key, windowSec, max) {
  const base = String($env['REDIS_CONNECTION_URL'] ?? '').replace(/\/+$/, '');
  const token = String($env['REDIS_REST_TOKEN'] ?? '').trim();
  if (!base) throw new Error('CRITICAL: REDIS_CONNECTION_URL missing from environment');
  const h = token ? { Authorization: `Bearer ${token}` } : {};
  const enc = encodeURIComponent(key);
  const incrRes = await fetch(`${base}/incr/${enc}`, { method: 'POST', headers: h });
  if (!incrRes.ok) throw new Error(`REDIS_HTTP_FAIL: incr ${incrRes.status}`);
  const incrData = await incrRes.json();
  const count = Number(incrData.result ?? 0);
  if (count === 1) {
    await fetch(`${base}/expire/${enc}/${windowSec}`, { method: 'POST', headers: h });
  }
  if (count > max) {
    throw new Error(`RATE_LIMIT: Caller exceeded ${max} req/${windowSec}s`);
  }
  return count;
}

function readHeader(h, name) {
  const target = name.toLowerCase();
  if (!h || typeof h !== 'object') return '';
  for (const [key, value] of Object.entries(h)) {
    if (String(key).toLowerCase() === target) return String(value ?? '').trim();
  }
  return '';
}

return (async () => {
  const body    = $input.first().json.body ?? {};
  const headers = $input.first().json.headers ?? {};

  const fromRaw = (body.From ?? '').toString().trim();
  await redisIncrWindow(`ratelimit:twilio:${fromRaw}`, 60, 5);

  const E164_REGEX  = /^\+[1-9]\d{6,14}$/;
  const DIGIT_REGEX = /^[0-9]?$/;

  const fromPhone = fromRaw;
  const digits    = (body.Digits ?? '').toString().trim();
  const callSid   = (body.CallSid ?? '').toString().trim();

  if (!E164_REGEX.test(fromPhone)) {
    throw new Error(`VALIDATION_FAIL: Invalid From number: '${fromPhone}'`);
  }
  if (!DIGIT_REGEX.test(digits)) {
    throw new Error(`VALIDATION_FAIL: Invalid Digits value: '${digits}'`);
  }

  const authToken = $env['N8N_TWILIO_AUTH_TOKEN'];
  if (authToken == null || String(authToken).trim() === '') {
    throw new Error('CRITICAL: Twilio Auth Token missing from environment');
  }

  const webhookBase = $env['N8N_WEBHOOK_BASE_URL'];
  if (webhookBase == null || String(webhookBase).trim() === '') {
    throw new Error('CRITICAL: N8N_WEBHOOK_BASE_URL missing from environment');
  }

  const twilioSig = readHeader(headers, 'x-twilio-signature');
    if (!twilioSig) {
      throw new Error('SECURITY: Missing x-twilio-signature header');
    }

    const query = $input.first().json.query ?? {};
    let webhookUrl = String(webhookBase).replace(/\/+$/, '') + '/webhook/twilio-voice-menu';
    const queryKeys = Object.keys(query).filter((k) => query[k] != null && String(query[k]) !== '');
    if (queryKeys.length > 0) {
      const qs = queryKeys
        .sort()
        .map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(String(query[k]))}`)
        .join('&');
      webhookUrl += '?' + qs;
    }

    const sortedParams = Object.keys(body)
      .sort()
      .map((k) => k + String(body[k] ?? ''))
      .join('');
    const validationStr = webhookUrl + sortedParams;
    const expectedSig = crypto
      .createHmac('sha1', String(authToken).trim())
      .update(validationStr, 'utf8')
      .digest('base64');

    if (!timingSafeEqualStrings(twilioSig, expectedSig)) {
      throw new Error('SECURITY: Twilio signature validation failed — possible spoofed request');
    }

  const isOptedOut = false;

  const tsLocal = new Date().toLocaleString('fr-MA', {
    timeZone: 'Africa/Casablanca',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  });

  return [{
    json: {
      fromPhone,
      digits,
      callSid,
      isOptedOut,
      tsLocal,
      validationPassed: true,
    },
  }];
})();

// ── Post-send update: mark the Baserow log row as Sent or Opted-Out ─────────
// We have the Baserow row id from Log Caller output and SMS result from Send SMS Link.
const logRowId   = $('Log Caller').item.json.id;           // Baserow auto-ID
const smsStatus  = $('Send SMS Link').item.json.status;    // e.g. 'queued', 'sent'
const isOptedOut = $('Validate & Rate-Limit Request').item.json.isOptedOut;

const finalStatus = isOptedOut ? 'Opted-Out' : (smsStatus ?? 'Sent');

return [{ json: { logRowId, finalStatus } }];

// Log fallback (bad digit pressed) to Baserow for UX analytics
const item = $('Validate & Rate-Limit Request').item.json;
return [{ json: {
  fromPhone:  item.fromPhone,
  digits:     item.digits,
  callSid:    item.callSid,
  tsLocal:    item.tsLocal,
  event:      'FALLBACK_BAD_DIGIT'
}}];
